public class FixedQueue implements ICharQ{private final char[] cells;private int head,size;public FixedQueue(int n){if(n<=0)throw new IllegalArgumentException();cells=new char[n];}public void put(char v)throws QueueFullException{if(size==cells.length)throw new QueueFullException();cells[(head+size++)%cells.length]=v;}public char get()throws QueueEmptyException{if(size==0)throw new QueueEmptyException();char v=cells[head];head=(head+1)%cells.length;size--;return v;}}
